TAB_Hearten[101] = {"Emilia",4,1,1,700001,1037,"Emilia có mái tóc trắng dài và đôi mắt tím, người ứng cử chức quốc vương đời thứ 42 của vương quốc Lugnica, tính cách tốt bụng hiền lành, có hơi ngốc.","Nếu tình yêu chân chính có màu sắc, thì đó nhất định là màu tím|Ta muốn đưa mọi người đến tương lai có thể vui cười",91,"Kết duyên nhận được",0,700001,710001}
TAB_Hearten[102] = {"Albedo",4,2,2,700002,1037,"Đảm nhiệm chức tổng quản Thủ Hộ của Đại Lăng Tẩm Nazarick, sống trong cung điện Ngai Vàng và một căn phòng ở tầng 9 của Đại Lăng Tẩm Nazarick.","Ta nên làm những gì|Ngươi muốn thế nào cũng được",130,"Mua được nhận",0,700002,710002}
TAB_Hearten[103] = {"Kamado Nezuko",4,3,3,700003,1037,"Em gái Kamado Tanjiro biến thành quỷ vì huyết dịch của Muzan. Không miệng, đơn thuần, thường dùng hành động để biểu đạt. Ghét ánh mặt trời, ban ngày đều thu nhỏ lại trốn trong chiếc rương đằng sau Kamado Tanjiro","Lời anh nói thì nhất định có thể làm được|Con người cần được bảo vệ và giúp đỡ, không thể làm hại họ",182,"Mua được nhận",0,700003,710003}
TAB_Hearten[104] = {"Roxy",4,4,4,700004,1037,"Sinh ra từ Ma tộc {Miglud}, ảo thuật gia cấp Thủy Vương, cũng là nhà thám hiểm cấp A. Ảnh hưởng từ chủng tộc nên luôn mang dáng vẻ nhỏ nhắn, ngoại hình 14 tuổi. Từng đảm nhiệm gia sư dạy ảo thuật của Rudius","Vậy ư? 10 năm sau nếu ngươi vẫn nghĩ như vậy, thì hãy nói lại cho ta nghe|Một ngày nào đó, sẽ có một người đàn ông cao lớn đầy khí thế...",205,"Mua được nhận",0,700004,710004}
TAB_Hearten[105] = {"Hancock",4,5,5,700005,1037,"Tên gọi: Nữ Vương Hải Tặc. Là hoàng đế đương nhiệm vương quốc Amazon-Lily của hải tặc ở Nữ Nhi Đảo, đồng thời cũng là thuyền trưởng nhóm hải tặc Cửu Xà, dung nhan được đánh giá là 'Thế giới đệ nhất mỹ nữ'. Từng là một trong các thành viên của Thất Vũ Hải. ","Cuối cùng đến đón ta rồi sao, thật là kẻ thích hóng chuyện |Cho dù thấy ta cũng không chút động lòng sao",217,"Mua được nhận",0,700005,710005}
TAB_Hearten[106] = {"Mai Shiranui",4,6,6,700006,1037,"Nữ Ninja hiện đại kế thừa nhẫn thuật Bất Tri Hỏa Lưu. Dùng cái quạt lớn làm vũ khí, mặc trang phục đỏ, để lộ ngực và chân (mục đích mê hoặc đối thủ), nhưng bên trong là một Yamato Nadeshiko thuần chất. ","Cần thêm Bất Tri Hỏa Lưu không?|Ngươi từ lúc bắt đầu mặt đã đỏ bừng bừng rồi, sốt sao?",233,"Mua được nhận",0,700006,710006}
TAB_Hearten[107] = {"C.C.",4,7,7,700007,1037,"Thiếu nữ thần bí cho người khác sức mạnh Geass. Có năng lực bất lão bất tử, được xem là 'Ma Nữ'. Tất cả năng lực Geass vô hiệu với cô ấy. Được gọi là 'Cái Khiên của Lelouch', có thể bảo vệ Lelouch về mặt tinh thần, là người duy nhất từ đầu tới cuối không phản bội Lelouch. ","Người đó cho ta mặt sàn ngủ|Tuy chỉ tiếp xúc gián tiếp, cũng có giá trị để thử",249,"Mua được nhận",0,700007,710007}
TAB_Hearten[108] = {"Đế Pháp",4,8,8,700008,1037,"Thành viên 'Tuyết Băng', 'Bộ mặt' của quán Bar 'Thiên Đường Thứ 7', kỹ thuật chiến đấu xuất sắc. Vẻ ngoài cởi mở nhưng thực tế khá hướng nội, thường một mình chịu đau khổ. Tính cởi mở mang đến ý chí mạnh mẽ, đủ để khắc phục sự yếu đuối bên trong.","Nói ta nghe câu chuyện sau khi ngươi rời thôn đi|Á… ngươi có phải đã hơi khác trước rồi?",262,"Mua được nhận",0,700008,710008}
TAB_Hearten[109] = {"Hoshino Ai",4,9,9,700009,1037,"Đứng đầu nhóm thần tượng 'Komachi B', có sức hút khó tả; chưa từng trải qua cảm giác yêu, rất mong có sự ấm áp gia đình, dù sự nghiệp thần tượng phát triển vẫn kiên quyết chọn nuôi dưỡng song thai.","Tậm trạng quá tốt|Làm thần tượng vẫn cực thú vị",270,"Mua được nhận",0,700009,710009}
TAB_Hearten[110] = {"Kikyo",4,10,10,700010,1037,"Một Miko nổi danh khắp thiên hạ, có linh lực mạnh mẽ bẩm sinh. Phụ trách bảo vệ và tịnh hóa Tứ Hồn Ngọc, đồng thời để bảo vệ mọi  người trong thôn mà không ngừng chiến đấu.","Muốn thử chút không?|Không cùng với ta sao?",272,"Mua được nhận",0,700010,710010}
